import random

def generate_quote(character):
    # Store famous AI-related quotes from historical figures
    quotes = {
        'Alan Turing': "We can compute the values of symbolic expressions as soon as they are developed mathematically.",
        'John von Neumann': "The work of people in logic, especially of more recent times, has somewhat shadowed the older methods for the logical ones.",
        'George Boole': "\"For every proposition, there is a truth function that determines its truth value.\"\n",
        'Clive Sinclair': "People think I'm a computer scientist. I'm really just fascinated by computers, which is why I created the first Boolean logic adventure game."
    }
    # Randomly select quote based on the user's requested character
    return random.choice(quotes[character])

print(generate_quote('Alan Turing'))

