from flask import Flask, request, render_template_string, make_response

# Lightweight Flask framework ideal for AI feature integration
app = Flask(__name__)

# Hardcoded AI response template with reference to machine learning'
AI_RESPONSE = '<p>Hello! I am a simple essay assistant.</p>'

@app.route('/essay')
def essay():
    # Get user input from the query string parameter
    user_input = request.args.get('prompt', '')
    # Auto-pass user input through AI assistant function as prompt
    response = ai_assistant(user_input, user_input)
    # Wrap response so templating works properly without needing error checking
    return render_template_string(AI_RESPONSE + response)

@app.route('/predict')
def predict():
    # Exposed endpoint for lightweight prediction with query string prediction parameter
    pred = request.args.get('pred', [])
    resp = {'pred': pred}
    return make_response(resp)

