from flask import Flask, request, g
import os

# Flask is a lightweight framework ideal for quickly prototyping APIs without boilerplate
app = Flask(__name__)

@app.route("/<source>/<resource_name>", methods=['GET', 'POST'])
def process_source(source, resource_name):
    # Retrieve source location and resource from URL
    # Use GET parameters from query string
    source = request.args['source']
    resource = request.args['resource']

    # For convenience, allow POST form data submission
    if request.method == 'POST':
        resource = request.form['resource']

    # Determine cache storage location based on connection info
    # Use user's roaming profile cache if available
    cache_dir = os.path.join('/studentResource', 'sharedResources', g.user)

    try:
        return open(os.path.join(cache_dir, resource), 'rb')
    except FileNotFoundError:
        return '{} not found'.format(resource)

if __name__ == "__main__":
    app.run()

